// @FIGURE_CODE_BEGIN
const W = 600;
const H = 900;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// 1. Background Layers
draw.rect(600, 200).move(0, 450).fill('#BCAAA4'); // Soil
draw.line(0, 450, 600, 450).stroke({ width: 2, color: '#795548' });

draw.rect(600, 250).move(0, 650).fill('#E6C25C'); // Solid sulfur deposit
draw.line(0, 650, 600, 650).stroke({ width: 2, color: '#A1887F' });

// 2. Liquid Sulfur Pool (animated later)
const pool = draw.path('M 120 900 Q 120 760 300 760 Q 480 760 480 900 Z').fill('#FFCA28');
pool.transform({ scale: 0.1, origin: [300, 850] }).opacity(0);

// 3. Fluid Polygons (Empty by default)
const emptyColor = '#FAFAFA';

const waterPoly1 = draw.polygon([
  [220, 300], [250, 300], [250, 750], [220, 750]
]).fill(emptyColor);

