// @FIGURE_CODE_BEGIN
const W = 600;
const H = 900;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// 1. Background Layers
draw.rect(600, 200).move(0, 450).fill('#BCAAA4'); // Soil
draw.line(0, 450, 600, 450).stroke({ width: 2, color: '#795548' });

draw.rect(600, 250).move(0, 650).fill('#E6C25C'); // Solid sulfur deposit
draw.line(0, 650, 600, 650).stroke({ width: 2, color: '#A1887F' });

// 2. Liquid Sulfur Pool (animated later)
const pool = draw.path('M 120 900 Q 120 760 300 760 Q 480 760 480 900 Z').fill('#FFCA28');
pool.transform({ scale: 0.1, origin: [300, 850] }).opacity(0);

// 3. Fluid Polygons (Empty by default)
const emptyColor = '#FAFAFA';

const waterPoly1 = draw.polygon([
  [220, 300], [250, 300], [250, 750], [220, 750]
]).fill(emptyColor);

const waterPoly2 = draw.polygon([
  [380, 400], [480, 400], [480, 350], [380, 350],
  [380, 300], [350, 300], [350, 750], [380, 750]
]).fill(emptyColor);

const waterPolys = [waterPoly1, waterPoly2];

const sulfurPoly = draw.polygon([
  [250, 780], [250, 180], [100, 180], [100, 130],
  [250, 130], [250, 100], [285, 100], [285, 820],
  [315, 820], [315, 250], [350, 250], [350, 780]
]).fill(emptyColor);

const airPoly = draw.polygon([
  [285, 820], [285, 30], [480, 30], [480, 80],
  [315, 80], [315, 820]
]).fill(emptyColor);

// Interactive hover regions
const waterGroup = draw.group().add(waterPoly1.clone().opacity(0)).add(waterPoly2.clone().opacity(0));
waterGroup.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Superheated water flows down the outer pipe', e))
  .on('mouseleave', hideTooltip);

sulfurPoly.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Sulfur mixture is forced up the middle pipe', e))
  .on('mouseleave', hideTooltip);

airPoly.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Compressed air is injected down the inner pipe', e))
  .on('mouseleave', hideTooltip);

pool.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Liquid sulfur pool', e))
  .on('mouseleave', hideTooltip);

// 4. Pipe Walls (Cutaway strokes)
