const arrowMarker = defs.marker(8, 8, function (add) {
  add.polygon('0,0 8,4 0,8').fill('#000');
}).ref(6, 4).size(8, 8).orient('auto');

function drawArrowPath(parent, d) {
  return parent.path(d).fill('none').stroke({ width: 2.5, color: '#000' }).marker('end', arrowMarker);
}

// Water Arrows
const waterArrows = draw.group().opacity(0);
drawArrowPath(waterArrows, 'M 480 375 L 430 375'); // Inlet
drawArrowPath(waterArrows, 'M 235 450 L 235 520'); // Left down
drawArrowPath(waterArrows, 'M 235 600 L 235 670');
drawArrowPath(waterArrows, 'M 365 450 L 365 520'); // Right down
drawArrowPath(waterArrows, 'M 365 600 L 365 670');
drawArrowPath(waterArrows, 'M 235 740 Q 235 790 180 800'); // Left curve out
drawArrowPath(waterArrows, 'M 365 740 Q 365 790 420 800'); // Right curve out

// Air Arrows
const airArrows = draw.group().opacity(0);
drawArrowPath(airArrows, 'M 480 55 L 430 55'); // Inlet
drawArrowPath(airArrows, 'M 300 180 L 300 250'); // Down
drawArrowPath(airArrows, 'M 300 350 L 300 420');
drawArrowPath(airArrows, 'M 300 520 L 300 590');
drawArrowPath(airArrows, 'M 300 690 L 300 760');
drawArrowPath(airArrows, 'M 300 815 Q 280 825 267.5 780'); // Curve up left
drawArrowPath(airArrows, 'M 300 815 Q 320 825 332.5 780'); // Curve up right

// Sulfur Arrows
const sulfurArrows = draw.group().opacity(0);
drawArrowPath(sulfurArrows, 'M 160 155 L 110 155'); // Outlet
drawArrowPath(sulfurArrows, 'M 267.5 700 L 267.5 630'); // Left up
drawArrowPath(sulfurArrows, 'M 267.5 530 L 267.5 460');
