    state: "idle"
  },
  {
    title: "Melting the sulfur",
    narration: "Superheated water is pumped down the outermost pipe, melting the surrounding solid sulfur into a liquid pool at the base.",
    state: "melt"
  },
  {
    title: "Injecting compressed air",
    narration: "Compressed air is forced down the innermost pipe directly into the liquid sulfur pool.",
    state: "aerate"
  },
  {
    title: "Extraction to the surface",
    narration: "The air creates a frothy, low-density mixture of liquid sulfur and water that is pushed up through the middle pipe to the surface.",
    state: "extract"
  }
];

let currentStep = 0;

window.setStep = function (idx) {
  currentStep = idx;
  const state = demo_steps[idx].state;
  const dur = 400;

  document.getElementById('stepLabel').textContent = demo_steps[idx].title;
  document.getElementById('demoNarration').textContent = demo_steps[idx].narration;
  document.getElementById('btnPrev').disabled = (currentStep === 0);
  document.getElementById('btnNext').disabled = (currentStep === demo_steps.length - 1);

  if (state === 'idle') {
    pool.animate(dur).opacity(0).transform({ scale: 0.1, origin: [300, 850] });
    waterPolys.forEach(p => p.animate(dur).fill(emptyColor));
    airPoly.animate(dur).fill(emptyColor);
    sulfurPoly.animate(dur).fill(emptyColor);

    waterArrows.animate(dur).opacity(0);
    airArrows.animate(dur).opacity(0);
    sulfurArrows.animate(dur).opacity(0);
  }
  else if (state === 'melt') {
    pool.animate(dur).opacity(1).transform({ scale: 1, origin: [300, 850] });
    waterPolys.forEach(p => p.animate(dur).fill('#B3E5FC'));
    airPoly.animate(dur).fill(emptyColor);
    sulfurPoly.animate(dur).fill(emptyColor);

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(0);
    sulfurArrows.animate(dur).opacity(0);
  }
  else if (state === 'aerate') {
    pool.animate(dur).opacity(1).transform({ scale: 1, origin: [300, 850] });
    waterPolys.forEach(p => p.animate(dur).fill('#B3E5FC'));
    airPoly.animate(dur).fill('#E0E0E0');
    sulfurPoly.animate(dur).fill(emptyColor);

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(1);
    sulfurArrows.animate(dur).opacity(0);
  }
  else if (state === 'extract') {
    pool.animate(dur).opacity(1).transform({ scale: 1, origin: [300, 850] });
    waterPolys.forEach(p => p.animate(dur).fill('#B3E5FC'));
    airPoly.animate(dur).fill('#E0E0E0');
    sulfurPoly.animate(dur).fill('#FFE082');

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(1);
    sulfurArrows.animate(dur).opacity(1);
  }
}

window.prevStep = function () {
  if (currentStep > 0) setStep(currentStep - 1);
}

window.nextStep = function () {
  if (currentStep < demo_steps.length - 1) setStep(currentStep + 1);
}

// Initialize figure
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

