Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="display:flex; flex-direction:column; gap:10px; padding: 4px;">
  <p id="demoNarration" style="margin:0; font-size:12px; color:#333; min-height:64px; line-height:1.45;"></p>
