  </div>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
const W = 600;
const H = 960;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// Colors
const colors = {
  empty: '#FAFAFA',
  water: '#85C1E9',
  air: '#E5E8E8',
  sulfur: '#F8C471',
  pool: '#F4D03F',
  soil: '#b08d6a',
  deposit: '#e8c368'
};

// 1. Background Layers
draw.rect(600, 250).move(0, 450).fill(colors.soil);
draw.line(0, 450, 600, 450).stroke({ width: 2, color: '#8d6d50' });

draw.rect(600, 260).move(0, 700).fill(colors.deposit);
draw.line(0, 700, 600, 700).stroke({ width: 2, color: '#c4a24c' });

// 2. Liquid Sulfur Pool (animated later)
const pool = draw.path('M 210 680 C 150 680, 80 750, 80 820 C 80 890, 180 910, 300 910 C 420 910, 520 890, 520 820 C 520 750, 450 680, 390 680 Z').fill(colors.pool);

// 3. Fluid Polygons (Bounded by the precise pipe geometries)
const waterPolyLeft = draw.path('M 240 300 L 150 300 L 150 400 L 200 400 L 200 600 L 210 680 L 240 680 Z').fill(colors.water);
const waterPolyRight = draw.path('M 360 300 L 450 300 L 450 310 L 460 310 L 460 360 L 450 360 L 450 400 L 400 400 L 400 600 L 390 680 L 360 680 Z').fill(colors.water);
const waterGroup = draw.group().add(waterPolyLeft).add(waterPolyRight);

const sulfurPolyLeft = draw.path('M 275 90 L 150 90 L 150 130 L 100 130 L 100 180 L 150 180 L 150 250 L 240 250 L 240 760 L 275 760 Z').fill(colors.sulfur);
const sulfurPolyRight = draw.path('M 325 90 L 450 90 L 450 250 L 360 250 L 360 760 L 325 760 Z').fill(colors.sulfur);
const sulfurGroup = draw.group().add(sulfurPolyLeft).add(sulfurPolyRight);

const airPoly = draw.path('M 460 40 L 320 40 Q 275 40 275 85 L 275 830 L 325 830 L 325 95 Q 325 80 340 80 L 460 80 Z').fill(colors.air);

// Interactive hover regions
waterGroup.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Superheated water flows down the outer pipe', e))
  .on('mouseleave', hideTooltip);

sulfurGroup.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Sulfur mixture is forced up the middle pipe', e))
  .on('mouseleave', hideTooltip);

airPoly.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Compressed air is injected down the inner pipe', e))
  .on('mouseleave', hideTooltip);

pool.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Liquid sulfur pool melted by the water', e))
  .on('mouseleave', hideTooltip);

// 4. Pipe Walls (Stepped housings, tapers, and staggered depths)
const sProp = { stroke: '#000', 'stroke-width': 5, fill: 'none', 'stroke-linejoin': 'miter', 'stroke-linecap': 'square' };

// Outer pipe (ends at Y=680, with inward tapers at the bottom)
draw.path('M 240 300 L 150 300 L 150 400 L 200 400 L 200 600 L 210 680').attr(sProp); // Left
draw.path('M 360 300 L 450 300 L 450 310 L 460 310').attr(sProp); // Right Top
draw.path('M 460 360 L 450 360 L 450 400 L 400 400 L 400 600 L 390 680').attr(sProp); // Right Bottom

// Middle pipe (ends at Y=760)
draw.path('M 275 90 L 150 90 L 150 130 L 100 130').attr(sProp); // Left Top
draw.path('M 100 180 L 150 180 L 150 250 L 240 250 L 240 760').attr(sProp); // Left Bottom
draw.path('M 325 90 L 450 90 L 450 250 L 360 250 L 360 760').attr(sProp); // Right

// Inner pipe (ends at Y=830)
draw.path('M 460 40 L 320 40 Q 275 40 275 85 L 275 830').attr(sProp); // Left
draw.path('M 460 80 L 340 80 Q 325 80 325 95 L 325 830').attr(sProp); // Right


// 5. Flow Arrows
const defs = draw.defs();
const arrowMarker = defs.marker(8, 8, function (add) {
  add.polygon('0,0 8,4 0,8').fill('#000');
}).ref(6, 4).size(8, 8).orient('auto');

function drawArrowPath(parent, d) {
  return parent.path(d).fill('none').stroke({ width: 2, color: '#000' }).marker('end', arrowMarker);
}

// Water Arrows
const waterArrows = draw.group();
drawArrowPath(waterArrows, 'M 470 335 L 420 335'); // Inlet
drawArrowPath(waterArrows, 'M 420 335 Q 380 335 380 380'); // Turn down right
drawArrowPath(waterArrows, 'M 220 335 L 220 380'); // Turn down left (implied 3D flow)
drawArrowPath(waterArrows, 'M 380 430 L 380 490'); // Right down
drawArrowPath(waterArrows, 'M 380 550 L 380 610');
drawArrowPath(waterArrows, 'M 220 430 L 220 490'); // Left down
drawArrowPath(waterArrows, 'M 220 550 L 220 610');
drawArrowPath(waterArrows, 'M 380 670 Q 380 720 430 750'); // Right curve out
drawArrowPath(waterArrows, 'M 220 670 Q 220 720 170 750'); // Left curve out

// Air Arrows
const airArrows = draw.group();
drawArrowPath(airArrows, 'M 470 60 L 420 60'); // Inlet
drawArrowPath(airArrows, 'M 420 60 Q 300 60 300 110'); // Curve down
drawArrowPath(airArrows, 'M 300 200 L 300 260'); // Down
drawArrowPath(airArrows, 'M 300 350 L 300 410');
drawArrowPath(airArrows, 'M 300 500 L 300 560');
drawArrowPath(airArrows, 'M 300 650 L 300 710');
drawArrowPath(airArrows, 'M 290 820 Q 257.5 860 257.5 760'); // Curve up left
drawArrowPath(airArrows, 'M 310 820 Q 342.5 860 342.5 760'); // Curve up right

// Sulfur Mixture Arrows
const sulfurArrows = draw.group();
drawArrowPath(sulfurArrows, 'M 140 155 L 90 155'); // Outlet
drawArrowPath(sulfurArrows, 'M 257.5 200 Q 257.5 155 200 155'); // Turn left to outlet
drawArrowPath(sulfurArrows, 'M 257.5 300 L 257.5 240'); // Left up
drawArrowPath(sulfurArrows, 'M 257.5 440 L 257.5 380');
drawArrowPath(sulfurArrows, 'M 257.5 580 L 257.5 520');
drawArrowPath(sulfurArrows, 'M 257.5 720 L 257.5 660');
drawArrowPath(sulfurArrows, 'M 342.5 300 L 342.5 240'); // Right up
drawArrowPath(sulfurArrows, 'M 342.5 440 L 342.5 380');
drawArrowPath(sulfurArrows, 'M 342.5 580 L 342.5 520');
drawArrowPath(sulfurArrows, 'M 342.5 720 L 342.5 660');
drawArrowPath(sulfurArrows, 'M 190 820 Q 257.5 820 257.5 750'); // Pool into left
drawArrowPath(sulfurArrows, 'M 410 820 Q 342.5 820 342.5 750'); // Pool into right


// 6. Labels
const fontProps = { family: 'sans-serif', size: 14 };

draw.text('Compressed air').move(470, 50).font({ ...fontProps, anchor: 'start' });
draw.text('Superheated\nwater').move(470, 315).font({ ...fontProps, anchor: 'start', leading: 1.2 });
draw.text('Sulfur, water,\nand air').move(90, 137).font({ ...fontProps, anchor: 'end', leading: 1.2 });

draw.text('Soil').move(100, 500).font({ ...fontProps, size: 16, anchor: 'middle' });
draw.line(100, 480, 100, 530).stroke({ width: 1.5, color: '#000' });

draw.text('Solid sulfur\ndeposit').move(100, 780).font({ ...fontProps, size: 16, anchor: 'middle', leading: 1.2 });

const lText = draw.text('Liquid sulfur').move(300, 920).font({ ...fontProps, size: 16, anchor: 'middle', weight: 'bold' });
lText.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });


// 7. Interactive Step Logic
const demo_steps = [
  {
    title: "Concentric pipe setup",
    narration: "The Frasch process avoids manual mining by sinking a three-pipe assembly directly into the solid sulfur deposit.",
    state: "idle"
  },
  {
    title: "Melting the sulfur",
    narration: "Superheated water is pumped down the outermost pipe, melting the surrounding solid sulfur into a liquid pool at the base.",
    state: "melt"
  },
  {
    title: "Injecting compressed air",
    narration: "Compressed air is forced down the innermost pipe directly into the liquid sulfur pool.",
    state: "aerate"
  },
  {
    title: "Extraction to the surface",
    narration: "The air creates a frothy, low-density mixture of liquid sulfur and water that is pushed up through the middle pipe to the surface.",
    state: "extract"
  }
];

let currentStep = 0;

function setVisualState(state) {
  const dur = 400;
  // Step 0 ("idle") defaults to showing the complete working process to perfectly replace the static image.
  if (state === 'idle' || state === 'extract') {
    pool.animate(dur).opacity(1);
    waterGroup.animate(dur).fill(colors.water);
    airPoly.animate(dur).fill(colors.air);
    sulfurGroup.animate(dur).fill(colors.sulfur);

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(1);
    sulfurArrows.animate(dur).opacity(1);
  }
  else if (state === 'melt') {
    pool.animate(dur).opacity(1);
    waterGroup.animate(dur).fill(colors.water);
    airPoly.animate(dur).fill(colors.empty);
    sulfurGroup.animate(dur).fill(colors.empty);

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(0);
    sulfurArrows.animate(dur).opacity(0);
  }
  else if (state === 'aerate') {
    pool.animate(dur).opacity(1);
    waterGroup.animate(dur).fill(colors.water);
    airPoly.animate(dur).fill(colors.air);
    sulfurGroup.animate(dur).fill(colors.empty);

    waterArrows.animate(dur).opacity(1);
    airArrows.animate(dur).opacity(1);
    sulfurArrows.animate(dur).opacity(0);
  }
}

window.setStep = function (idx) {
  currentStep = idx;
  const stepData = demo_steps[idx];

  document.getElementById('stepLabel').textContent = stepData.title;
  document.getElementById('demoNarration').textContent = stepData.narration;
  document.getElementById('btnPrev').disabled = (currentStep === 0);
  document.getElementById('btnNext').disabled = (currentStep === demo_steps.length - 1);

  setVisualState(stepData.state);
}

window.prevStep = function () {
  if (currentStep > 0) setStep(currentStep - 1);
}

window.nextStep = function () {
  if (currentStep < demo_steps.length - 1) setStep(currentStep + 1);
}

// Initialize default state
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

